import hashlib
import math

class BloomFilter:
    """
    A Bloom filter implementation that uses a bit array and multiple hash functions
    to provide an efficient probabilistic method of checking membership of an item in a set.
    The design choices are based on the formula for optimal size of the bit array and
    the number of hash functions for a given expected number of items and false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.size = self.optimal_size(expected_items, false_positive_rate)
        self.hash_count = self.optimal_hash_count(expected_items, self.size)
        self.bit_array = [0] * self.size

    def optimal_size(self, n: int, p: float) -> int:
        """Calculate the optimal size of the bit array."""
        return int(-n * math.log(p) / (math.log(2) ** 2))

    def optimal_hash_count(self, n: int, m: int) -> int:
        """Calculate the optimal number of hash functions."""
        return int((m / n) * math.log(2))

    def _hashes(self, item: str):
        """Generate multiple hash values for the given item."""
        hash_values = set()
        for i in range(self.hash_count):
            # Create a unique hash for each hash function
            hash_input = f"{item}-{i}".encode('utf-8')
            hash_output = int(hashlib.md5(hash_input).hexdigest(), 16)
            hash_values.add(hash_output % self.size)
        return hash_values

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter."""
        for index in self._hashes(item):
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is possibly in the Bloom filter."""
        return all(self.bit_array[index] for index in self._hashes(item))

