    def _calculate_hash_functions(self, n: int, m: int) -> int:
        """Calculate the optimal number of hash functions."""
        if n == 0 or m == 0:
            return 0
        return max(1, int((m / n) * math.log(2)))

    def _hash(self, item: str, seed: int) -> int:
        """Compute a hash using a simple combined approach with different seeds."""
        hash_input = f"{item}{seed}".encode('utf-8')
        return int(hashlib.sha256(hash_input).hexdigest(), 16) % self.size

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter."""
        for i in range(self.hash_count):
            index = self._hash(item, i)
            self.bit_array[index] = 1

